          const predZ = p.z + vel.z * tCross + 0.5 * gustZ * tCross * tCross;

          const brakeDist = ( Math.max(0, vel.x) * Math.max(0, vel.x) ) / 5.2;
          const canAbort = dx > brakeDist + 0.055 && dx > 0.075;

          const unsafeZ = Math.abs(p.z - gz) > 0.078 || Math.abs(predZ - gz) > 0.088;
          const unsafeY = Math.abs(p.y - gy) > 0.135 || Math.abs(predY - gy) > 0.155;

          if (canAbort && (unsafeZ || unsafeY)) {
            phase = 'align';
            settle = 0;
            const alignX = gx - 0.42;
            target = { x: alignX, y: gy, z: gz };
            refRaw.x = Math.min(refRaw.x, alignX);
            ref.x = Math.min(ref.x, p.x - 0.05);
          } else {
            target = { x: gx + 0.34, y: gy, z: gz };
          }
        }

        if (phase === 'exit') {
          target = { x: gx + 0.34, y: gy, z: gz };
        }
      } else {
        // 7. Ramp pad descent
        const pad = obs.pad.centre;
        const distXZ = Math.hypot(pad.x - p.x, pad.z - p.z);
        const spdXZ = Math.hypot(vel.x, vel.z);

        if (phase !== 'descend') {
          const approachY = clamp(0.28 + 0.65 * distXZ, 0.32, 0.75);
          target = { x: pad.x, y: approachY, z: pad.z };
          if (distXZ < 0.095 && spdXZ < 0.22 && Math.abs(p.y - approachY) < 0.14) {
            phase = 'descend';
            padY = p.y;
          }
        }

        if (phase === 'descend') {
          if (distXZ < 0.125) {
            const rate = p.y > 0.22 ? 0.40 : 0.22;
            padY = Math.max(0.015, padY - rate * dt);
          } else if (p.y > 0.11) {
            padY = Math.max(padY, 0.15);
          }
          target = { x: pad.x, y: padY, z: pad.z };
        }
      }

      // 4. Smooth reference filter
      const prevRef = { x: ref.x, y: ref.y, z: ref.z };
      const inGateLock = phase === 'cross' || phase === 'exit';
      const maxRateX = inGateLock ? 1.65 : 1.85;
      const maxRateY = phase === 'descend' ? 0.55 : 1.45;
      const maxRateZ = inGateLock ? 1.80 : 1.85;

      refRaw.x += clamp(target.x - refRaw.x, -maxRateX * dt, maxRateX * dt);
      refRaw.y += clamp(target.y - refRaw.y, -maxRateY * dt, maxRateY * dt);
      refRaw.z += clamp(target.z - refRaw.z, -maxRateZ * dt, maxRateZ * dt);

      const alphaRef = inGateLock ? 0.18 : 0.14;
      ref.x += alphaRef * (refRaw.x - ref.x);
      ref.y += alphaRef * (refRaw.y - ref.y);
      ref.z += alphaRef * (refRaw.z - ref.z);

      const refVelX = (ref.x - prevRef.x) / dt;
      const refVelY = (ref.y - prevRef.y) / dt;
      const refVelZ = (ref.z - prevRef.z) / dt;

      // 3. Yaw + local position integrals
      const errTargetX = target.x - p.x;
      const errTargetY = target.y - p.y;
      const errTargetZ = target.z - p.z;

      if (Math.abs(errTargetX) < 0.32 && phase !== 'cross' && phase !== 'exit') {
        intPos.x = clamp(intPos.x + errTargetX * dt, -0.35, 0.35);
      } else {
        intPos.x *= 0.95;
      }

      if (Math.abs(errTargetZ) < 0.32) {
        intPos.z = clamp(intPos.z + errTargetZ * dt, -0.35, 0.35);
      } else {
        intPos.z *= 0.95;
      }

      if (p.y > 0.085 && Math.abs(errTargetY) < 0.45) {
        intPos.y = clamp(intPos.y + (ref.y - p.y) * dt, -0.6, 0.6);
      }

      const kpX = inGateLock ? 4.8 : 4.4;
      const kdX = inGateLock ? 3.8 : 3.5;
      const kpZ = inGateLock ? 5.6 : 4.6;
      const kdZ = inGateLock ? 4.2 : 3.6;
      const kiXZ = 1.8;

      const distX = dSlow.x + 0.95 * gustX;
      const distY = dSlow.y + 0.45 * gustY;
      const distZ = dSlow.z + 0.95 * gustZ;

      const ax = clamp(
        kpX * (ref.x - p.x) + kdX * (refVelX - vel.x) + kiXZ * intPos.x + (drag0 / m0) * vel.x - distX,
        -4.2,
        4.2
      );
      const az = clamp(
        kpZ * (ref.z - p.z) + kdZ * (refVelZ - vel.z) + kiXZ * intPos.z + (drag0 / m0) * vel.z - distZ,
        -4.2,
        4.2
      );
      const ay = clamp(
        6.0 * (ref.y - p.y) + 4.0 * (refVelY - vel.y) + 2.2 * intPos.y + (drag0 / m0) * vel.y - distY,
        -4.0,
        5.0
      );

      const cy = Math.cos(att.yaw);
      const sy = Math.sin(att.yaw);
      const totalAccY = Math.max(4.0, g + ay);

      let maxTilt = 0.48;
      let thrust;
      if (
        phase === 'descend' &&
        p.y <= 0.092 &&
        padY <= 0.04 &&
        Math.hypot(obs.pad.centre.x - p.x, obs.pad.centre.z - p.z) <= 0.14
      ) {
        maxTilt = 0.08;
        thrust = 0.08;
      } else {
        if (phase === 'descend' && p.y <= 0.14) maxTilt = 0.15;
        const tiltScale = Math.max(0.65, Math.cos(att.roll) * Math.cos(att.pitch));
        thrust = clamp((m0 * (g + ay)) / (16 * tiltScale), 0.05, 1.0);
      }

      const pitch = clamp((cy * ax - sy * az) / totalAccY, -maxTilt, maxTilt);
      const roll = clamp(-(sy * ax + cy * az) / totalAccY, -maxTilt, maxTilt);

      intYaw = clamp(intYaw + att.yaw * dt, -0.5, 0.5);
      const yawRate = clamp(-3.2 * att.yaw - 2.4 * intYaw - 0.25 * obs.rates.yaw, -2, 2);

      thrustEst += (thrust - thrustEst) * (1 - Math.exp(-dt / 0.04));

      return { thrust, roll, pitch, yawRate };
    },
  };
}

